export interface ConnectorConfig {
  mailchimpApiKey: string;
  datadogApiKey: string;
  fetch?: typeof fetch;
  maxRetries?: number;
  baseDelayMs?: number;
}

export interface MailchimpRequest {
  url: string;
  method: string;
  headers?: Record<string, string>;
  body?: unknown;
}

export interface MailchimpResponse {
  status_code: number;
  headers: Record<string, string>;
  body: unknown;
}

export interface MailchimpFailedCall {
  originalRequest: MailchimpRequest;
  failedResponse: MailchimpResponse;
}

export interface ConnectorResult {
  datadogEventId: string;
  retriesAttempted: number;
  finalStatus: number;
  finalRetryAfter: string | number | null;
}

function parseRetryAfter(headerValue: string | undefined): number {
  if (!headerValue) return NaN;
  const asInt = parseInt(headerValue, 10);
  if (!isNaN(asInt)) return asInt * 1000;
  const asDate = new Date(headerValue).getTime();
  if (!isNaN(asDate)) return asDate - Date.now();
  return NaN;
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function buildBasicAuthHeader(apiKey: string): string {
  const credentials = `apikey:${apiKey}`;
  return `Basic ${btoa(credentials)}`;
}

function btoa(str: string): string {
  if (typeof Buffer !== 'undefined') {
    return Buffer.from(str).toString('base64');
  }
  if (typeof btoa === 'function') {
    return btoa(str);
  }
  return btoaPolyfill(str);
}

function btoaPolyfill(str: string): string {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=';
  let result = '';
  let i = 0;
  while (i < str.length) {
    const c1 = str.charCodeAt(i++);
    const c2 = i < str.length ? str.charCodeAt(i++) : NaN;
    const c3 = i < str.length ? str.charCodeAt(i++) : NaN;
    const b1 = c1 >> 2;
    const b2 = ((c1 & 3) << 4) | (c2 >> 4);
    const b3 = isNaN(c2) ? 64 : ((c2 & 15) << 2) | (c3 >> 6);
    const b4 = isNaN(c3) ? 64 : c3 & 63;
    result += chars[b1] + chars[b2] + chars[b3] + chars[b4];
  }
  return result;
}

export async function handle(
  payload: MailchimpFailedCall,
  config: ConnectorConfig
): Promise<ConnectorResult> {
  const fetchImpl = config.fetch ?? fetch;
  const maxRetries = config.maxRetries ?? 3;
  const baseDelayMs = config.baseDelayMs ?? 1000;

  if (!payload.originalRequest?.url) {
    throw new Error('originalRequest.url is required');
  }
  if (!payload.originalRequest?.method) {
    throw new Error('originalRequest.method is required');
  }
  if (typeof payload.failedResponse?.status_code !== 'number') {
    throw new Error('failedResponse.status_code is required and must be a number');
  }
  if (!payload.failedResponse?.headers) {
    throw new Error('failedResponse.headers is required');
  }

  const { originalRequest, failedResponse } = payload;
  let response = failedResponse;
  let retriesAttempted = 0;
  let retryIndex = 0;

  const makeMailchimpRequest = async (): Promise<MailchimpResponse> => {
    const headers: Record<string, string> = {
      Authorization: buildBasicAuthHeader(config.mailchimpApiKey),
      'Content-Type': 'application/json',
      ...originalRequest.headers,
    };
    const res = await fetchImpl(originalRequest.url, {
      method: originalRequest.method,
      headers,
      body: originalRequest.body ? JSON.stringify(originalRequest.body) : undefined,
    });
    const responseHeaders: Record<string, string> = {};
    res.headers.forEach((value, key) => {
      responseHeaders[key.toLowerCase()] = value;
    });
    let body: unknown;
    const contentType = res.headers.get('content-type') ?? '';
    if (contentType.includes('application/json')) {
      body = await res.json();
    } else {
      body = await res.text();
    }
    return {
      status_code: res.status,
      headers: responseHeaders,
      body,
    };
  };

  while (response.status_code === 429 && retryIndex < maxRetries) {
    const retryAfterMs = parseRetryAfter(response.headers['retry-after']);
    const exponentialMs = baseDelayMs * 2 ** retryIndex;
    const delayMs = Math.max(isNaN(retryAfterMs) ? 0 : retryAfterMs, exponentialMs);
    if (delayMs > 0 && !isNaN(delayMs)) {
      await sleep(delayMs);
    }
    response = await makeMailchimpRequest();
    retriesAttempted++;
    retryIndex++;
  }

  const finalStatus = response.status_code;
  const finalRetryAfter = response.headers['retry-after'] ?? null;
  const finalBody = response.body;

  const timestamp = Math.floor(Date.now() / 1000);
  const eventBody = {
    title: 'Mailchimp API Rate Limit Exceeded',
    text: `Final status: ${finalStatus}, Retry-After: ${finalRetryAfter}, Response body: ${JSON.stringify(finalBody)}`,
    timestamp,
    priority: 'normal' as const,
    source: 'mailchimp',
    tags: ['integration:mailchimp', 'retry_exhausted'],
  };

  const datadogRes = await fetchImpl('https://api.datadoghq.com/api/v2/events', {
    method: 'POST',
    headers: {
      'DD-API-KEY': config.datadogApiKey,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(eventBody),
  });

  if (!datadogRes.ok) {
    const errorText = await datadogRes.text();
    throw new Error(`Datadog Events API error: ${datadogRes.status} ${datadogRes.statusText} - ${errorText}`);
  }

  const datadogData = (await datadogRes.json()) as { id?: string; event_id?: string; event?: { id: string } };
  const datadogEventId = datadogData.id ?? datadogData.event_id ?? datadogData.event?.id ?? 'unknown';

  return {
    datadogEventId,
    retriesAttempted,
    finalStatus,
    finalRetryAfter,
  };
}

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { handle, ConnectorConfig, MailchimpFailedCall, ConnectorResult } from './connector';
import { fakeFetch, jsonResponse, contractFetch, SOURCE_EXAMPLE, TARGET_ENDPOINTS } from './fixtures';

const STATUS_TEXT: Record<number, string> = {
  200: 'OK', 201: 'Created', 202: 'Accepted', 204: 'No Content',
  400: 'Bad Request', 401: 'Unauthorized', 403: 'Forbidden', 404: 'Not Found', 409: 'Conflict',
  422: 'Unprocessable Entity', 429: 'Too Many Requests',
  500: 'Internal Server Error', 502: 'Bad Gateway', 503: 'Service Unavailable',
};

function responseWithHeaders(body: unknown, status: number, extraHeaders: Record<string, string> = {}): Response {
  return new Response(JSON.stringify(body), {
    status,
    statusText: STATUS_TEXT[status] ?? '',
    headers: { 'Content-Type': 'application/json', ...extraHeaders },
  });
}

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch();
    const testInput: MailchimpFailedCall = {
      ...SOURCE_EXAMPLE,
      originalRequest: { url: 'https://api.mailchimp.com/3.0/', method: 'GET' },
      failedResponse: { status_code: 429, headers: { 'retry-after': '1' }, body: { detail: 'rate limited' } },
    } as MailchimpFailedCall;
    const config: ConnectorConfig = {
      mailchimpApiKey: 'test-mailchimp-key',
      datadogApiKey: 'test-datadog-key',
      fetch,
      maxRetries: 1,
      baseDelayMs: 10,
    };
    const result = await handle(testInput, config);
    expect(calls.length).toBeGreaterThan(0);
    expect(result.retriesAttempted).toBeGreaterThanOrEqual(0);
  });
});

describe('handle', () => {
  const baseConfig: ConnectorConfig = {
    mailchimpApiKey: 'mc-key-123',
    datadogApiKey: 'dd-key-456',
    maxRetries: 3,
    baseDelayMs: 10,
  };

  const validInput: MailchimpFailedCall = {
    originalRequest: {
      url: 'https://api.mailchimp.com/3.0/lists',
      method: 'GET',
      headers: { 'User-Agent': 'test' },
    },
    failedResponse: {
      status_code: 429,
      headers: { 'retry-after': '2' },
      body: { type: 'https://mailchimp.com/error', title: 'TooManyRequests', status: 429, detail: 'Rate limited' },
    },
  };

  it('happy path: retries Mailchimp then posts to Datadog', async () => {
    let mailchimpCallCount = 0;
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://api.mailchimp.com/3.0/lists' && req.method === 'GET') {
        mailchimpCallCount++;
        if (mailchimpCallCount <= 2) {
          return jsonResponse({ type: 'error', title: 'TooManyRequests', status: 429, detail: 'Rate limited' }, 429);
        }
        return jsonResponse({ success: true }, 200);
      }
      if (req.url === 'https://api.datadoghq.com/api/v2/events' && req.method === 'POST') {
        expect(req.headers.get('dd-api-key')).toBe('dd-key-456');
        expect(req.json).toMatchObject({
          title: 'Mailchimp API Rate Limit Exceeded',
          source: 'mailchimp',
          tags: expect.arrayContaining(['integration:mailchimp', 'retry_exhausted']),
        });
        return jsonResponse({ id: 'evt-123' }, 201);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    const result = await handle(validInput, { ...baseConfig, fetch });
    expect(result).toEqual({
      datadogEventId: 'evt-123',
      retriesAttempted: 3,
      finalStatus: 200,
      finalRetryAfter: null,
    });
    expect(mailchimpCallCount).toBe(3);
    expect(calls.length).toBe(4);
  });

  it('respects Retry-After header when larger than exponential backoff', async () => {
    let mailchimpCallCount = 0;
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://api.mailchimp.com/3.0/lists' && req.method === 'GET') {
        mailchimpCallCount++;
        if (mailchimpCallCount === 1) {
          return responseWithHeaders({ detail: 'rate limited' }, 429, { 'Retry-After': '5' });
        }
        return jsonResponse({ success: true }, 200);
      }
      if (req.url === 'https://api.datadoghq.com/api/v2/events' && req.method === 'POST') {
        return jsonResponse({ id: 'evt-456' }, 201);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    const result = await handle(validInput, { ...baseConfig, fetch, baseDelayMs: 10 });
    expect(result.retriesAttempted).toBe(2);
    expect(result.finalStatus).toBe(200);
    expect(calls.length).toBe(3);
  });

  it('uses exponential backoff when Retry-After is absent', async () => {
    let mailchimpCallCount = 0;
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://api.mailchimp.com/3.0/lists' && req.method === 'GET') {
        mailchimpCallCount++;
        if (mailchimpCallCount <= 2) {
          return jsonResponse({ detail: 'rate limited' }, 429);
        }
        return jsonResponse({ success: true }, 200);
      }
      if (req.url === 'https://api.datadoghq.com/api/v2/events' && req.method === 'POST') {
        return jsonResponse({ id: 'evt-789' }, 201);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    const result = await handle(validInput, { ...baseConfig, fetch, baseDelayMs: 10 });
    expect(result.retriesAttempted).toBe(3);
    expect(result.finalStatus).toBe(200);
    expect(calls.length).toBe(4);
  });

  it('parses HTTP-date Retry-After header', async () => {
    const futureDate = new Date(Date.now() + 5000).toISOString();
    let mailchimpCallCount = 0;
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://api.mailchimp.com/3.0/lists' && req.method === 'GET') {
        mailchimpCallCount++;
        if (mailchimpCallCount === 1) {
          return responseWithHeaders({ detail: 'rate limited' }, 429, { 'Retry-After': futureDate });
        }
        return jsonResponse({ success: true }, 200);
      }
      if (req.url === 'https://api.datadoghq.com/api/v2/events' && req.method === 'POST') {
        return jsonResponse({ id: 'evt-date' }, 201);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    const result = await handle(validInput, { ...baseConfig, fetch, baseDelayMs: 10 });
    expect(result.retriesAttempted).toBe(2);
    expect(result.finalStatus).toBe(200);
    expect(calls.length).toBe(3);
  });

  it('stops retrying after maxRetries and posts final 429 to Datadog', async () => {
    let mailchimpCallCount = 0;
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://api.mailchimp.com/3.0/lists' && req.method === 'GET') {
        mailchimpCallCount++;
        return responseWithHeaders({ detail: 'rate limited' }, 429, { 'Retry-After': '1' });
      }
      if (req.url === 'https://api.datadoghq.com/api/v2/events' && req.method === 'POST') {
        expect(req.json).toMatchObject({
          text: expect.stringContaining('Final status: 429'),
        });
        return jsonResponse({ id: 'evt-exhausted' }, 201);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    const result = await handle(validInput, { ...baseConfig, fetch, maxRetries: 2, baseDelayMs: 5 });
    expect(result.retriesAttempted).toBe(2);
    expect(result.finalStatus).toBe(429);
    expect(result.finalRetryAfter).toBe('1');
    expect(mailchimpCallCount).toBe(2);
    expect(calls.length).toBe(3);
  });

  it('throws descriptive error when originalRequest.url is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const badInput = { ...validInput, originalRequest: { ...validInput.originalRequest, url: '' } };
    await expect(handle(badInput, { ...baseConfig, fetch })).rejects.toThrow('originalRequest.url is required');
  });

